rlabels <- c(lr = "Règle linéaire", og = "Ecarts de production au carré",  ib = "Impulsions au carré", mixte = "Mixte (écarts de prod. et impulsions au carré)")
vlabs <- c(ibc = "Impulsion", ogc = "Ecart de production", ib = "Impulsion", og = "Ecart de production")
doptim <- simulations$pertes |> 
  filter(between(year, 2025, 2050)) |>
  pivot_longer(c(og, ogc, ib, ibc), names_to = "variable") |> 
  mutate(
    cumul = ifelse(str_detect(variable, "c$"), "c", "nc"),
    variable = str_sub(variable, 1,2)  ) |> 
  pivot_wider(names_from = cumul, values_from = value) |> 
  group_by(variable, df, perte) |> 
  arrange(year) |> 
  ungroup() |> 
  pivot_longer(cols = c(c, nc)) |> 
  mutate(
    cum = case_when(
      name == "c" ~ "Cumulé",
      name == "nc" ~ "Non cumulé" )  ) |> 
  pivot_wider(names_from = quantile, values_from = value) |> 
  mutate(
    perte = factor(perte, c("lr", "og", "ib", "mixte")),
    dfl = ifelse(perte!="lr", str_c(" ; \u03b2=", round(100-100*df),"%"),""),
    tooltip = glue("<b>{rlabels[perte]}{dfl}</b><br>{year}<br>{vlabs[variable]} : {round(mean*100,1)}%"))
dpsmt <- cc |> filter(variable=="ib",ibs == "psmt", year>=2025, year<=2029)

ggo <- function(x) {
  ggplot(doptim |> filter(year>=2025, variable == "ib", cum == "Non cumulé", dstar == x )) +
    PrettyCols::scale_color_pretty_c(
    "Blues",
    breaks = c(0, 0.05, 0.1), labels=c("100%", "95%", "90%"), name = "\u03b2") +
  PrettyCols::scale_fill_pretty_c("Blues") +
  # geom_line(
  #   data = cc |> filter(variable=="ib",ibs == "psmt", year>=2025, year<=2029),
  #   aes(x = year, y = mean), color = "grey80", size=.25) +
  geom_hline(yintercept = 0, linewidth = 0.1) +
  geom_ribbon(aes(x=year, ymin=q0.025, ymax=q0.975, group=df, fill = df), alpha=0.1) +
  geom_segment(data = dpsmt, aes(x=year, yend=mean, y=0, xend=year), color="orange", linewidth=0.1)+
  geom_point_interactive(
    data = dpsmt,
    aes(
      x = year, y = mean, data_id = year,
      tooltip = glue(
        "<b>Programme de stabilité à moyen terme (PSMT)</b><br>{year}<br>Impulsion: {round(mean*100)}%")), 
    hover_nearest = TRUE,  size = .25, color = "orange") +
    geom_line(
      aes(x = year, y = mean, color = (df), group=df))+
    geom_point_interactive(
      aes(x = year, y = mean, fill = df, group=df,
          tooltip = tooltip, data_id = year), 
      color="white", shape=21, size = 1, stroke=0.25, hover_nearest = TRUE)+
    scale_size_manual(values= c("obs" = 0, "pmst"=0, "rule" = 1.5)) +
    scale_shape_manual(values= c("obs" = 21, "pmst"=21, "rule" = 21)) +
    facet_wrap(
      vars(perte),
      labeller = as_labeller(rlabels)) +
    scale_y_continuous(labels = scales::label_percent(.1), limits = c(-0.02, 0.02))+
    scale_x_continuous(breaks = scales::pretty_breaks()) +
    xlab(NULL)+ylab(NULL)+
    theme_ofce()+
    guides(shape = "none", fill="none", size = "none", color = guide_legend(nrow=1))+
    labs(color = NULL, fill=NULL) +
    theme(legend.position.inside = c(0.0, 0.36),
          legend.justification = c(0,1),
          legend.direction = "horizontal") +
    ofce_caption(
      source = "debtwatch 2.0, AMECO printemps 2025",
      note = "Les impulsions sont calculées suivant une politique budgétaire optimale (i.e. minimisant la fonction de perte considérée) et aboutissant à {round(x*100)}% de dette en 2045 à partir de 2025.")
}
dstars <- distinct(doptim, dstar) |> pull(dstar)
names(dstars) <- str_c("d*=", round(dstars*100),"%")
tabset <-  map(dstars, ~ ggo(.x))

tabsetize(tabset)
