Ajustement en fonction de la cible de dette
:::
:::


Le @fig-sensibminog représente le lien entre l'ajustement nécessaire et le creusement de l'écart de production induit. Cet exercice repose sur une valeur moyenne du multiplicateur de 0,65 la première année, et serait plus marqué pour un multiplicateur plus important. Le surajustement du PSMT se traduit par un creux plus profond de 0,3 point de PIB ou de façon équivalente 0,3 point de chômage.


::: {#cell-fig-sensibminog .cell}

```{.r .cell-code .hidden}
lprd <- c(psmt ="cumul de 2025 à 2029", full = "entre 2025 à 2050")
libs <- c(optimal = "Optimal depuis 2025", psmt = "PSMT jusqu'en 2029, puis optimal")
gminog <- bo$mins |>
  filter(variable == "minog", period %in% c("full"), 
         ibs %in% c("psmt", "optimal"), ecstar %in% c(0), infstar == 0.0175)  |> 
  mutate(period = factor(period, c("psmt", "full")),
         tooltip = glue("<b>{lprd[period]}</b><br>{libs[ibs]}<br>d*={round(dstar*100,1)}% min(og)={round(mean*100,2)}%")) |> 
  ggplot() +
  aes(x=dstar, y = mean, color=ibs, group=ibs)+
  geom_ribbon(aes(ymin = q0.025, ymax = q0.975), alpha =0.1, color = "transparent") + 
  scale_colour_pretty_d("Joyful", name = NULL, labels = libs) +
  scale_fill_pretty_d("Joyful", name = NULL, labels = libs) +
  geom_line()+
  scale_y_continuous(labels = label_percent(.1)) +
  scale_x_continuous(labels = label_percent(1)) +
  ylab("Minimum de l'écart de production")+
  xlab("d*")+
  geom_point_interactive(
    aes(tooltip=tooltip, data_id = dstar, fill = ibs),
    size = 1, shape = 21, color = "grey90", hover_nearest = TRUE) +
  guides(color = guide_legend(title = NULL), fill = guide_legend(title = NULL))+
  theme_ofce(
    legend.position.inside = c(0.02, 0.98)
  )


gmaxd <- bo$mins |>
  filter(variable == "maxd", period %in% c("full"), 
         ibs %in% c("psmt", "optimal"), ecstar %in% c(0), infstar == 0.0175)  |> 
  mutate(period = factor(period, c("psmt", "full")),
         tooltip = glue("<b>{lprd[period]}</b><br>{libs[ibs]}<br>d*={round(dstar*100,1)}% max(dette)={round(mean*100,2)}%")) |> 
  ggplot() +
  aes(x=dstar, y = mean, color=ibs, group=ibs)+
  geom_ribbon(aes(ymin = q0.025, ymax = q0.975), alpha =0.1, color = "transparent") + 
  scale_colour_pretty_d("Joyful", name = NULL, labels = libs) +
  scale_fill_pretty_d("Joyful", name = NULL, labels = libs) +
  geom_line()+
  scale_y_continuous(labels = label_percent(1)) +
  scale_x_continuous(labels = label_percent(1)) +
  ylab("Maximum de dette")+
  xlab("d*")+
  geom_point_interactive(
    aes(tooltip=tooltip, data_id = dstar, fill = ibs),
    size = 1, shape = 21, color = "grey90", hover_nearest = TRUE) +
  guides(color = guide_legend(title = NULL), fill = guide_legend(title = NULL))+
  theme_ofce(
    legend.position.inside = c(0.02, 0.98)
  )
library(patchwork)
gg <- gminog / gmaxd

girafy(gg)
```

