  mutate(
    libc1 = str_c("min: ",round(min(q0.5[year>=2029])*100, 2), "%"),
    libc2 = str_c("final: ", round(q0.5[year==max(year)]*100, 2), "%"),
    libc = ifelse(year==2030, str_c(libc1, "   \n", libc2), NA_character_)) |> 
  ungroup() |> 
  ggplot() +
  aes(y =q0.5, ymin=q0.25, ymax =q0.75, 
