    labels=scales::label_percent(1),
    oob = scales::squish)+
  guides(color = guide_legend(nrow = 1)) +
  theme_ofce(
    legend.position = "bottom",
    legend.direction = "horizontal",
    legend.key.width = unit(24, "pt"),
    legend.text.position = "bottom",
    legend.title = marquee::element_marquee(vjust = 0.9),
    panel.spacing = unit(12, "pt")
  )+
  facet_grid(
    rows=vars(ecstar), cols=vars(ib),
    labeller = as_labeller(
      c("0.005"="Ecart critique -0.5%", "0"="Ecart critique nul", "-0.005"="Ecart critique 0.5%",
        psmt = "PSMT", optimal = "Optimal", frontload = "Frontload", backload = "Backload")
    )) +
  xlab("Cible de dette")+
  ylab("Cumul de l'écart de production")
